#define E_BUDGET_NO_MAIN
#include "e_budget_relaxed_hnsw.cpp"

#include <deque>

namespace {
using namespace vann;
struct Summary{std::vector<float>center;float radius=0;};

class BlockCodec{
public:
 explicit BlockCodec(const HnswIndex&h):d(h.dimension()),lo(d,INFINITY),span(d),code(h.size()*d){std::vector<float>hi(d,-INFINITY);for(size_t id=0;id<h.size();++id)for(int j=0;j<d;++j){lo[j]=std::min(lo[j],h.vector(id)[j]);hi[j]=std::max(hi[j],h.vector(id)[j]);}for(int j=0;j<d;++j)span[j]=hi[j]-lo[j];for(size_t id=0;id<h.size();++id)for(int j=0;j<d;++j){double u=span[j]>0?(h.vector(id)[j]-lo[j])/span[j]:0;code[id*d+j]=uint8_t(std::clamp(int(std::floor(u*16)),0,15));}}
 float code_distance(int a,int b)const{float s=0;for(int j=0;j<d;++j){float z=float(code[size_t(a)*d+j])-code[size_t(b)*d+j];s+=z*z;}return s;}
 Summary summarize(const HnswIndex&h,const std::vector<int>&members)const{std::vector<float>mean(d);for(int id:members)for(int j=0;j<d;++j)mean[j]+=h.vector(id)[j]/members.size();Summary z;z.center.resize(d);for(int j=0;j<d;++j){int p=span[j]>0?std::clamp(int(std::floor((mean[j]-lo[j])/span[j]*16)),0,15):0;z.center[j]=lo[j]+span[j]*((p+.5F)/16);}for(int id:members)z.radius=std::max(z.radius,std::sqrt(squared_l2(h.vector(id),z.center.data(),d)));return z;}
 int d;std::vector<float>lo,span;std::vector<uint8_t>code;
};

std::vector<int> seeds(const HnswIndex&h){std::vector<int>o;std::vector<uint8_t>seen(h.size());std::deque<int>q;q.push_back(h.index->hnsw.entry_point);seen[q.front()]=1;while(!q.empty()){int u=q.front();q.pop_front();o.push_back(u);for(int l=h.index->hnsw.levels[u]-1;l>=0;--l)for(int v:h.neighbors(u,l))if(!seen[v])seen[v]=1,q.push_back(v);}for(size_t i=0;i<h.size();++i)if(!seen[i])o.push_back(i);return o;}

std::vector<std::vector<int>> make_blocks(const HnswIndex&h,const BlockCodec&codec,int bs){std::vector<std::vector<int>>g(h.size());for(size_t id=0;id<h.size();++id){g[id]=h.neighbors(id,0);std::sort(g[id].begin(),g[id].end());g[id].erase(std::unique(g[id].begin(),g[id].end()),g[id].end());}auto order=seeds(h);std::vector<int>owner(h.size(),-1);std::vector<std::vector<int>>blocks;
 for(int seed:order){if(owner[seed]>=0)continue;int bi=blocks.size();blocks.push_back({seed});owner[seed]=bi;std::unordered_set<int>frontier;auto add=[&](int u){for(int v:g[u])if(owner[v]<0)frontier.insert(v);};add(seed);
  while(int(blocks.back().size())<bs&&!frontier.empty()){std::vector<int>cand;for(int v:frontier)if(owner[v]<0)cand.push_back(v);if(cand.empty())break;std::unordered_set<int>boundary;for(int u:blocks.back())boundary.insert(g[u].begin(),g[u].end());struct M{int id,links,overlap;float radius,code;double rank=0;};std::vector<M>m;for(int v:cand){auto members=blocks.back();members.push_back(v);auto s=codec.summarize(h,members);int links=0,overlap=0;for(int u:blocks.back())links+=std::binary_search(g[v].begin(),g[v].end(),u);for(int x:g[v])overlap+=boundary.count(x);m.push_back({v,links,overlap,s.radius,codec.code_distance(seed,v),0});}auto rank=[&](auto value,bool descending){std::vector<int>x(m.size());std::iota(x.begin(),x.end(),0);std::sort(x.begin(),x.end(),[&](int a,int b){auto va=value(m[a]),vb=value(m[b]);return descending?va>vb:va<vb;});for(size_t r=0;r<x.size();++r)m[x[r]].rank+=r;};rank([](const M&x){return x.links;},true);rank([](const M&x){return x.overlap;},true);rank([](const M&x){return x.radius;},false);rank([](const M&x){return x.code;},false);auto best=std::min_element(m.begin(),m.end(),[](const M&a,const M&b){return a.rank<b.rank||(a.rank==b.rank&&a.id<b.id);});int v=best->id;frontier.erase(v);owner[v]=bi;blocks.back().push_back(v);add(v);}
  while(int(blocks.back().size())<bs){auto it=std::find_if(order.begin(),order.end(),[&](int x){return owner[x]<0;});if(it==order.end())break;owner[*it]=bi;blocks.back().push_back(*it);}std::sort(blocks.back().begin(),blocks.back().end());}
 return blocks;}
}

int main()try{using namespace vann;Config c;c.queries=100;Matrix base=read_fvecs(c.dataset+"/sift_base.fvecs",c.base),queries=read_fvecs(c.dataset+"/sift_query.fvecs",c.queries);HnswIndex h=build_hnsw(base,c.M,c.efc,c.cache);base.values.clear();base.values.shrink_to_fit();ESQ sq(h);BlockCodec codec(h);auto gt=ground_truth(h,queries,c.k);std::ofstream out("verification_block_screen_q100.csv");out<<"block_size,block_count,avg_radius,avg_candidate_blocks,avg_candidate_objects,candidate_inflation,avg_excluded_blocks,block_exclusion_ratio,avg_excluded_objects,object_exclusion_ratio,avg_opened_blocks,avg_opened_objects,avg_refined_sq6,avg_raw,recall_at_10,summary_kib,opened_sq4_kib,delta46_kib,raw_kib,member_ids_kib,mac_kib,screen_payload_kib,current_object_payload_kib,bound_violations\n";
for(int bs:{2,4}){auto blocks=make_blocks(h,codec,bs);std::vector<int>owner(h.size());std::vector<Summary>summary(blocks.size());double ravg=0;uint64_t violations=0;for(size_t b=0;b<blocks.size();++b){summary[b]=codec.summarize(h,blocks[b]);ravg+=summary[b].radius;for(int id:blocks[b]){owner[id]=b;float d=std::sqrt(squared_l2(h.vector(id),summary[b].center.data(),h.dimension()));if(d>summary[b].radius+1e-4F)++violations;}}double cb=0,co=0,eb=0,eo=0,ob=0,oo=0,ref=0,raw=0,hits=0,sumb=0,sq4b=0,db=0,rb=0,idb=0;
 for(int qi=0;qi<c.queries;++qi){auto tr=run_e(h,sq,queries.row(qi),c.k,64,"sq4");std::vector<int>bids;for(int id:tr.disclosed)bids.push_back(owner[id]);std::sort(bids.begin(),bids.end());bids.erase(std::unique(bids.begin(),bids.end()),bids.end());std::vector<int>candidates;for(int b:bids)candidates.insert(candidates.end(),blocks[b].begin(),blocks[b].end());std::sort(candidates.begin(),candidates.end());candidates.erase(std::unique(candidates.begin(),candidates.end()),candidates.end());std::vector<DistanceId>exact;for(int id:candidates)exact.push_back({squared_l2(queries.row(qi),h.vector(id),h.dimension()),id});std::partial_sort(exact.begin(),exact.begin()+c.k,exact.end(),better);exact.resize(c.k);float tau=exact.back().distance;std::unordered_set<int>answer;for(auto z:exact)answer.insert(z.id);for(int id:gt[qi])hits+=answer.count(id);std::vector<int>opened;for(int b:bids){float center=std::sqrt(squared_l2(queries.row(qi),summary[b].center.data(),h.dimension()));float lb=std::max(0.0F,center-summary[b].radius);if(std::nextafter(lb*lb,0.0F)>tau){++eb;eo+=blocks[b].size();}else{++ob;opened.insert(opened.end(),blocks[b].begin(),blocks[b].end());}}for(int id:opened)if(sq.lower(queries.row(qi),id,4)<=tau){++ref;if(sq.lower(queries.row(qi),id,6)<=tau)++raw;}cb+=bids.size();co+=candidates.size();oo+=opened.size();sumb+=bids.size()*108.0;sq4b+=opened.size()*64.0;db+=ref*0;idb+=opened.size()*4.0;}
 // Re-run byte-stage counts without cumulative-counter ambiguity.
 ref=raw=db=rb=0;for(int qi=0;qi<c.queries;++qi){auto tr=run_e(h,sq,queries.row(qi),c.k,64,"sq4");std::vector<int>bids;for(int id:tr.disclosed)bids.push_back(owner[id]);std::sort(bids.begin(),bids.end());bids.erase(std::unique(bids.begin(),bids.end()),bids.end());std::vector<int>cand;for(int b:bids)cand.insert(cand.end(),blocks[b].begin(),blocks[b].end());std::sort(cand.begin(),cand.end());cand.erase(std::unique(cand.begin(),cand.end()),cand.end());std::vector<DistanceId>x;for(int id:cand)x.push_back({squared_l2(queries.row(qi),h.vector(id),h.dimension()),id});std::partial_sort(x.begin(),x.begin()+c.k,x.end(),better);float tau=x[c.k-1].distance;for(int b:bids){float dc=std::sqrt(squared_l2(queries.row(qi),summary[b].center.data(),h.dimension()));float lb=std::max(0.F,dc-summary[b].radius);if(std::nextafter(lb*lb,0.F)>tau)continue;for(int id:blocks[b])if(sq.lower(queries.row(qi),id,4)<=tau){++ref;db+=32;idb+=4;if(sq.lower(queries.row(qi),id,6)<=tau){++raw;rb+=512;idb+=4;}}}}
 double nq=c.queries,mac=80.0/1024,screen=(sumb+sq4b+db+rb+idb)/nq/1024+mac,current=70.2468;out<<bs<<','<<blocks.size()<<','<<ravg/blocks.size()<<','<<cb/nq<<','<<co/nq<<','<<(co/nq/811.86)<<','<<eb/nq<<','<<eb/cb<<','<<eo/nq<<','<<eo/co<<','<<ob/nq<<','<<oo/nq<<','<<ref/nq<<','<<raw/nq<<','<<hits/(nq*c.k)<<','<<sumb/nq/1024<<','<<sq4b/nq/1024<<','<<db/nq/1024<<','<<rb/nq/1024<<','<<idb/nq/1024<<','<<mac<<','<<screen<<','<<current<<','<<violations<<'\n';std::cout<<"bs="<<bs<<" blocks="<<cb/nq<<" objects="<<co/nq<<" excluded="<<eb/cb*100<<"% openedObj="<<oo/nq<<" recall="<<hits/(nq*c.k)<<" screen="<<screen<<" KiB violations="<<violations<<'\n';}return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
